if (!customElements.get('product-filter')) {
    customElements.define('product-filter', class Filter extends HTMLElement {
        constructor() {
            super();
            const _this = this;
            this.form = this.querySelector('form');
            this.form.addEventListener('input', function(e) {
                _this.formSubmit(e);
            });
            const viewButton = this.querySelector('.js-collection-filter-view');
            const clearButton = this.querySelector('.js-collection-filter-clear');

            if (viewButton) {
                viewButton.addEventListener('click', function(e) {
                    e.preventDefault();
                    _this.submitCurrentFilters();
                });
            }
            if (clearButton) {
                clearButton.addEventListener('click', function(e) {
                    e.preventDefault();
                    _this.clearFilters();
                });
            }
        }

        formSubmit(evt) {
            if (evt.isTrusted && window.matchMedia('(max-width: 767px)').matches) {
                return;
            }
            if (evt.target.closest('form')) {
                const url = this.buildFilterUrl(evt.target.closest('form'));
                const sectionId = this.getAttribute('data-section');
                closeFilterPopup();
                this.updateContent(url, sectionId)
            }
        }

        buildFilterUrl(form) {
            const formData = new FormData(form);
            const searchParams = new URLSearchParams(formData).toString();
            const baseUrl = this.getAttribute('data-url');

            if (baseUrl.includes('?')) {
                return `${baseUrl}&${searchParams}`;
            }

            return `${baseUrl}?${searchParams}`;
        }

        submitCurrentFilters() {
            if (this.form) {
                const url = this.buildFilterUrl(this.form);
                const sectionId = this.getAttribute('data-section');

                closeFilterPopup();
                this.updateContent(url, sectionId);
            }
        }

        clearFilters() {
            if (this.form) {
                this.form.querySelectorAll('input[type="checkbox"]:checked').forEach(function(checkbox) {
                    checkbox.checked = false;
                });
            }
        }

        updateContent(url, section) {
            if (document.querySelector('.js-catalog__content')) {
				document.querySelector('.js-catalog__content').classList.add('loading');
            }
            let _this = this;
            fetch(url + `&section_id=${section}`).then(function(response) {
                return response.text();
            }).then(function(responseText) {
                const doc = new DOMParser().parseFromString(responseText, 'text/html');
                const fetchFilter = doc.querySelector('[data-product-filter]');
                const fetchProductGrid = doc.querySelector('[data-product-grid]');
                const fetchPagination = doc.querySelector('[data-pagination]');
                const fetchDesktopFilterSelect = doc.querySelector('[data-desktop-filter] .collection-filter-select');
                const fetchDesktopFilterCheckbox = doc.querySelector('[data-desktop-filter] .collection-filter-dropdown-list');
                const fetchDesktopFilterValue = doc.querySelector('[data-desktop-filter] .filter-value');
                const fetchProductCount = doc.querySelector('[data-product-count]');
                const filter = document.querySelector('[data-product-filter]');
                const productGrid = document.querySelector('[data-product-grid]');
                const pagination = document.querySelector('[data-pagination]');
				const desktopFilterSelect = document.querySelector('[data-desktop-filter] .collection-filter-select');
				const desktopFilterCheckbox = document.querySelector('[data-desktop-filter] .collection-filter-dropdown-list');
				const desktopFilterValue = document.querySelector('[data-desktop-filter] .filter-value');
				const productCount = document.querySelector('[data-product-count]');

                if (fetchProductGrid && productGrid) {
                    productGrid.innerHTML = fetchProductGrid.innerHTML
                }
                if (fetchPagination && pagination) {
                    pagination.innerHTML = fetchPagination.innerHTML
                }
                if (fetchFilter && filter) {
                    filter.innerHTML = fetchFilter.innerHTML
                }
                if (fetchDesktopFilterSelect && desktopFilterSelect) {
					desktopFilterSelect.innerHTML = fetchDesktopFilterSelect.innerHTML
                }
                if (fetchDesktopFilterCheckbox && desktopFilterCheckbox) {
					desktopFilterCheckbox.innerHTML = fetchDesktopFilterCheckbox.innerHTML
                }
                if (fetchDesktopFilterValue && desktopFilterValue) {
					desktopFilterValue.innerHTML = fetchDesktopFilterValue.innerHTML
                }
                if (fetchProductCount && productCount) {
					productCount.innerHTML = fetchProductCount.innerHTML
                }

                reloadFilterEvents();
                window.history.replaceState({}, '', url);
                if (document.querySelector('.js-catalog__content')) {
                    document.querySelector('.js-catalog__content').classList.remove('loading');
                }
				if (window.lazyLoadEnabled == "true") {
                    reloadLazyLoad();
                }
				reloadProductCardHover();
				if (window.CollectionDisplay) {
					window.CollectionDisplay.refresh();
				}
            }).catch(function (err) {
                console.error('Something went wrong.', err);
            });
        }

    });
}


function debounce(fn, wait) {
    let t;
    return (...args) => {
        clearTimeout(t);
        t = setTimeout(() => fn.apply(this, args), wait);
    };
}

function closeFilterPopup() {
	if (document.querySelector('#collection-filter')) {
		document.querySelector('#collection-filter').classList.remove('open');
	}
	document.body.classList.remove('disable-scroll');
}

function reloadFilterEvents() {
	let collectionFilterButton = document.querySelectorAll(".collection-top-filter .js-collection-filter-trigger");
	if (collectionFilterButton) {
		collectionFilterButton.forEach(function (button) {
			button.addEventListener('click', function () {
				if (this.dataset.type == 'open') {
					if (document.querySelector('#collection-filter')) {
						document.querySelector('#collection-filter').classList.add('open');
						document.body.classList.add('disable-scroll');
					}
				} else {
					if (document.querySelector('#collection-filter')) {
						document.querySelector('#collection-filter').classList.remove('open');
						document.body.classList.remove('disable-scroll');
					}
				}
			});
		});
	}

	let collectionFilter = document.querySelectorAll('.js-collection-filter-select');
	if (collectionFilter) {
		collectionFilter.forEach(function (select) {
			let label = select.dataset.label;
			new TomSelect(select, {
				controlInput: null,
				render: {
					item: function (data, escape) {
						return `<div class="select-label">
						<span class="select-label-inner">
							<span>${label}</span>
							<span class="icon-wrapper">
								<span class="icon icon-plus"></span>
								<span class="icon icon-minus"></span>
							</span>
							<span>//</span>
						</span>
						<span>
						${escape(data.text)}
						</span>
					
					</div>`;
					},
					option: function (data, escape) {
						return `<div class="select-option">
						<span class="radio-dot"></span>
						<span>
						${escape(data.text)}
						</span>
					</div>`;
					}
				}
			});
		});
	}
	desktopSelectEvent();
	desktopCheckboxEvent();
}
function desktopSelectEvent(){
	let collectionFilter = document.querySelectorAll('.js-collection-filter-select');
	if(collectionFilter){
		collectionFilter.forEach(function (select){
			select.addEventListener("change",function (){
				if(document.querySelector('product-filter')){
					if(document.querySelector('product-filter').querySelector(`input[name="${this.name}"][value="${this.value}"]`)){
						document.querySelector('product-filter').querySelector(`input[name="${this.name}"][value="${this.value}"]`).checked = true;
						if(document.querySelector('product-filter').querySelector('form')){
							document.querySelector('product-filter').querySelector('form').dispatchEvent(new Event('input'));
						}
					}
				}

			});
		})
	}
}
desktopSelectEvent();
