function setCollectionPreloaderSize() {
    let catalog = document.querySelector('.js-catalog__content');
    let catalogProducts = document.querySelector('.js-catalog__content [data-product-grid]');
    if (catalogProducts) {
        let scrollY = window.scrollY;
        let screenHeight = window.outerHeight;
        let catalogProductsTop = catalogProducts.offsetTop;
        let catalogProductsHeight = catalogProducts.offsetHeight + parseInt(window.getComputedStyle(catalog).getPropertyValue('margin-bottom'));
        let preloader = catalog.querySelector('.js-catalog__content-preloader');
        let footerTop = document.querySelector('.footer').getBoundingClientRect().top


        if ((catalogProductsTop - scrollY) > 0) {
            preloader.style.height = screenHeight - (catalogProductsTop - scrollY) + 'px';
            preloader.style.top = (catalogProductsTop - scrollY) + 'px';
        } else {
            preloader.style.height = screenHeight + 'px';
            preloader.style.top = 0;
        }
        if (footerTop < screenHeight) {
            if (footerTop > 0) {
                preloader.style.height = footerTop + 'px';
            } else {
                preloader.style.height = 0 + 'px';
            }
        }
    }
}
setCollectionPreloaderSize();
window.addEventListener('scroll', setCollectionPreloaderSize)
